import urllib.request, json, os
from datetime import datetime, timezone

token = os.environ.get("GITHUB_TOKEN")
if not token:
    print("NO_TOKEN")
    exit(0)

workflows = ["ajaybot-paper.yml", "ajaybot-monitor.yml"]
now = datetime.now(timezone.utc)
print(f"Current UTC time: {now.isoformat()}")

results = {}
for wf in workflows:
    try:
        url = f"https://api.github.com/repos/nothing12837-lang/ajaybot/actions/workflows/{wf}/runs?per_page=1"
        req = urllib.request.Request(url)
        req.add_header("Authorization", f"token {token}")
        req.add_header("Accept", "application/vnd.github.v3+json")
        with urllib.request.urlopen(req, timeout=15) as r:
            data = json.loads(r.read())
        if not data.get("workflow_runs"):
            results[wf] = {"status": "never_run", "age_minutes": None}
        else:
            run = data["workflow_runs"][0]
            created_at_str = run.get("created_at")
            # Parse ISO 8601
            created_at = datetime.fromisoformat(created_at_str.replace("Z", "+00:00"))
            age = (now - created_at).total_seconds() / 60.0
            results[wf] = {
                "name": run.get("name"),
                "status": run.get("status"),
                "conclusion": run.get("conclusion"),
                "created_at": created_at_str,
                "age_minutes": age
            }
    except Exception as e:
        results[wf] = {"error": str(e)}

print(json.dumps(results, indent=2))
'"}

